package com.aoo.bcg.share;
import com.fasterxml.jackson.databind.ObjectMapper;import java.net.URI;import java.net.http.*;import java.util.Map;import java.time.Duration;
public final class HttpInviteRewardPort implements InviteRewardPort{private final HttpClient http;private final URI base;private final String token;private final ObjectMapper json;public HttpInviteRewardPort(URI base,String token,ObjectMapper json){this.http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(3)).build();this.base=base;this.token=token;this.json=json;if(token==null||token.length()<32)throw new IllegalArgumentException("referral token required");}
 public String grant(JdbcInviteLinkRepository.Consumption c)throws Exception{byte[]body=json.writeValueAsBytes(Map.of("action","inviteReward","consumptionId",c.consumptionId(),"inviteId",c.inviteId(),"issuerId",c.issuerId(),"consumerId",c.consumerId(),"kind",c.kind(),"targetId",c.targetId()));HttpRequest r=HttpRequest.newBuilder(base.resolve("/v1/invite-rewards")).timeout(Duration.ofSeconds(5)).header("Authorization","Bearer "+token).header("X-API-Version","1").header("Idempotency-Key","invite-consumption:"+c.consumptionId()).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofByteArray(body)).build();HttpResponse<String>x=http.send(r,HttpResponse.BodyHandlers.ofString());if(x.statusCode()!=200)throw new IllegalStateException("invite reward dependency rejected request");@SuppressWarnings("unchecked")Map<String,Object>p=json.readValue(x.body(),Map.class);@SuppressWarnings("unchecked")Map<String,Object>d=(Map<String,Object>)p.get("data");return String.valueOf(d.get("reference"));}}
